<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, watch, nextTick, provide } from 'vue'
import FilePanel from './FilePanel.vue'
import KeysPanel from './KeysPanel.vue'
import DocumentContent from './DocumentContent.vue'
import HostEditor from './HostEditor.vue'
import RulesEditor from './RulesEditor.vue'
import PlanEditor from './PlanEditor.vue'
import OptionsEditor from './OptionsEditor.vue'
import AuthenticationPrompt from './AuthenticationPrompt.vue'
import UiIcon from './UiIcon.vue'
import userGuide from '../USER_GUIDE.md?raw'
import { SessionKey,type Environment,type EnvironmentSession,newHost,newRule,endpoint,states,type Host,type Rule,type Plan,type State,type Config,type Group,type Preview,type StartResult } from './api'
import { clone,normalizeRule,ruleErrors,pruneRules,hostChanged,browserAddress,optionKey } from './editor'
import { sshOptions } from './ssh-options'
import { useRowMenus } from './useRowMenus'
import SortHandle from './SortHandle.vue'
import { useSortable, moveItem, type SortMove } from './useSortable'
import { vDialogDismiss } from './dialogDismiss'
const props=defineProps<{session:EnvironmentSession;initial:State;environment:Environment;distributions:{name:string;running:boolean;version:number}[];switching:boolean;environmentError:string}>()
const emit=defineEmits<{switch:[distro?:string];enumerate:[]}>()
provide(SessionKey,props.session)
const api=props.session.request
const shell=ref<HTMLElement>()
useRowMenus(shell)
const filePanel=ref<InstanceType<typeof FilePanel>>(),environmentDialog=ref<HTMLDialogElement>()
const state=ref<State|null>(props.initial),page=ref('主机'),search=ref(''),filter=ref('all'),error=ref(''),notice=ref('')
const pendingKeys=ref(new Set<string>()),actionErrors=ref<Record<string,string>>({})
const busy=(key:string)=>pendingKeys.value.has(key)
const help=ref<HTMLDialogElement>(),helpTrigger=ref<HTMLButtonElement>(),dialog=ref<HTMLDialogElement>(),previewDialog=ref<HTMLDialogElement>(),confirmDialog=ref<HTMLDialogElement>()
const currentPrompt=computed(()=>state.value?.prompts[0]),answer=ref(''),promptId=ref('')
const selected=ref<string[]>([]),collapsed=ref<string[]>(readPreference('collapsed',[]))
const hostDraft=ref<Host|null>(null),ruleDraft=ref<Rule[]>([]),planDraft=ref<Plan|null>(null),editorKind=ref(''),editorTab=ref('connection'),editorError=ref(''),baseline=ref(''),editorRevision=ref(''),editorBaseConfig=ref<Config|null>(null),adoptGroup=ref('')
const preview=ref<Preview|null>(null),previewSearch=ref(''),result=ref<StartResult|null>(null),lastRequest=ref<{ruleIds:string[];planId?:string;overrides:string[]}|null>(null),overrides=ref<string[]>([])
const configDraft=ref(''),configBaseline=ref(''),configRevision=ref('')
const theme=ref('system');let timer:ReturnType<typeof setInterval>,noticeTimer:ReturnType<typeof setTimeout>;let refreshing=false,editorTrigger:HTMLElement|null=null
const media=matchMedia('(prefers-color-scheme: dark)')
function readPreference<T>(key:string,fallback:T):T{try{const value=JSON.parse(localStorage.getItem(`tether-${props.session.environment}-${key}`)||'null');return Array.isArray(fallback)?(Array.isArray(value)?value as T:fallback):value??fallback}catch{return fallback}}
function applyTheme(){document.documentElement.dataset.theme=theme.value==='system'?(media.matches?'dark':'light'):theme.value}
watch(theme,applyTheme);media.addEventListener('change',applyTheme)
watch(collapsed,value=>{try{localStorage.setItem(`tether-${props.session.environment}-collapsed`,JSON.stringify(value))}catch{}},{deep:true})
function notify(message:string){notice.value=message;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',4500)}
async function refresh(){if(refreshing)return;refreshing=true;try{state.value=await api<State>('status');theme.value=state.value.config.theme;selected.value=selected.value.filter(id=>state.value!.config.rules.some(r=>r.id===id))}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{refreshing=false}}
async function run(key:string,fn:()=>Promise<unknown>){if(busy(key))return false;pendingKeys.value=new Set([...pendingKeys.value,key]);delete actionErrors.value[key];try{await fn();return true}catch(e){actionErrors.value[key]=e instanceof Error?e.message:String(e);return false}finally{const next=new Set(pendingKeys.value);next.delete(key);pendingKeys.value=next;await refresh()}}
async function saveConfig(c:Config,revision=state.value!.revision){await api('save',{config:c,revision})}
const cloneConfig=()=>clone(state.value!.config)
let sortBase:{config:Config;revision:string}|null=null
useSortable(shell,reorder,()=>{if(!state.value||busy('sort')||editorKind.value)return false;sortBase={config:cloneConfig(),revision:state.value.revision};return true})
async function reorder(move:SortMove){
 if(!sortBase)return
 const {config,revision}=sortBase;sortBase=null
 const items=move.group==='hosts'?config.hosts:move.group==='plans'?config.plans:config.rules
 if(move.group.startsWith('rules:')&&!items.every(item=>item.id!==move.source&&item.id!==move.target||'hostId' in item&&move.group===`rules:${item.hostId}`))return
 if(!moveItem<{id:string}>(items,move))return
 await run('sort',async()=>{await saveConfig(config,revision);notify('顺序已保存')})
}
const allHosts=computed(()=>{const all=[...(state.value?.config.hosts??[])];for(const g of state.value?.groups??[])if(!all.some(h=>h.id===g.hostId))all.push(g.snapshot.host);return all})
function hostGroups(id:string){return state.value?.groups.filter(g=>g.hostId===id)??[]}
function hostRules(id:string){return state.value?.config.rules.filter(r=>r.hostId===id)??[]}
function displayRules(id:string){const all=[...hostRules(id)];for(const g of hostGroups(id))for(const r of g.rules)if(!all.some(x=>x.id===r.id||x.hostId===r.hostId&&x.direction===r.direction&&x.bind===r.bind&&x.port===r.port&&x.target===r.target&&x.targetPort===r.targetPort))all.push(r);return all}
function ruleGroup(r:Rule){return state.value?.groups.find(g=>g.desired&&g.rules.some(x=>x.id===r.id))??state.value?.groups.find(g=>g.rules.some(x=>x.id===r.id))}
function pending(r:Rule){const g=ruleGroup(r);if(!g?.desired)return false;const old=g.rules.find(x=>x.id===r.id)!;const h=state.value?.config.hosts.find(h=>h.id===r.hostId);return (['hostId','direction','bind','port','target','targetPort'] as const).some(k=>r[k]!==old[k])||!!h&&hostChanged(h,g.snapshot.host)}
function externalMatch(r:Rule){return state.value?.portChecks?.find(x=>x.ruleId===r.id)}
function ruleState(r:Rule){return pending(r)?'pending':ruleGroup(r)?.desired?ruleGroup(r)!.state:externalMatch(r)?.state==='unverified'?(ruleGroup(r)?.state||'idle'):externalMatch(r)?.state||ruleGroup(r)?.state||'idle'}
function groupPending(g:Group){return g.rules.some(old=>{const current=state.value?.config.rules.find(r=>r.id===old.id);return current?pending(current):false})||!!state.value?.config.hosts.some(h=>h.id===g.hostId&&hostChanged(h,g.snapshot.host))}
const matchesRule=(r:Rule)=>{
 const h=allHosts.value.find(h=>h.id===r.hostId),q=search.value.toLowerCase();const text=`${h?.name} ${h?.destination} ${h?.notes} ${r.name} ${r.notes} ${endpoint(r)}`.toLowerCase()
 const s=ruleState(r);return text.includes(q)&&(filter.value==='all'||filter.value==='running'&&s==='running'||filter.value==='idle'&&s==='idle'||filter.value==='error'&&['failed','pending','reconnecting','unavailable','checking'].includes(s))
}
const visibleRules=(id:string)=>displayRules(id).filter(matchesRule)
const hosts=computed(()=>allHosts.value.filter(h=>visibleRules(h.id).length||!displayRules(h.id).length&&filter.value==='all'&&`${h.name} ${h.destination} ${h.notes}`.toLowerCase().includes(search.value.toLowerCase())))
const activeCount=computed(()=>state.value?.groups.filter(g=>g.desired).length||0)
const navigation=[{label:'主机',icon:'host'},{label:'计划',icon:'plan'},{label:'密钥',icon:'key'},{label:'设置',icon:'settings'}]
const pageMeta=computed(()=>page.value==='计划'?`${state.value?.config.plans.length??0} 个启动计划 · ${state.value?.config.rules.length??0} 条可引用映射`:page.value==='密钥'?'身份文件与 SSH Agent':page.value==='设置'?'SSH 文件、本地配置与偏好':`${state.value?.config.hosts.length??0} 台主机 · ${activeCount.value} 个托管连接`)
const registered=(r:Rule)=>state.value?.config.rules.some(x=>x.id===r.id)
const isHostRegistered=(id:string)=>state.value?.config.hosts.some(x=>x.id===id)
const failedIds=computed(()=>result.value?.results.filter(r=>r.state!=='running'&&state.value?.config.rules.some(x=>x.id===r.ruleId)).map(r=>r.ruleId)||[])
const resultCounts=computed(()=>({reused:result.value?.results.filter(r=>r.state==='running'&&r.reused).length||0,started:result.value?.results.filter(r=>r.state==='running'&&!r.reused).length||0,failed:result.value?.results.filter(r=>r.state!=='running').length||0}))
const editorState=()=>JSON.stringify({host:hostDraft.value,rules:ruleDraft.value,plan:planDraft.value})
const dirty=computed(()=>!!editorKind.value&&editorState()!==baseline.value)
function openHost(h?:Host,tab='connection',add=false,focusRule=''){editorTrigger=document.activeElement as HTMLElement;hostDraft.value=h?clone(h):newHost();ruleDraft.value=h?clone(hostRules(h.id)):[];planDraft.value=null;editorKind.value='host';editorTab.value=tab;editorError.value='';editorRevision.value=state.value!.revision;editorBaseConfig.value=cloneConfig();adoptGroup.value='';delete actionErrors.value['preview-draft'];baseline.value=editorState();if(add){const r=newRule(hostDraft.value.id);while(ruleDraft.value.some(x=>x.port===r.port))r.port++;ruleDraft.value.push(r);focusRule=r.id}dialog.value?.showModal();if(focusRule)void nextTick(()=>{const row=[...document.querySelectorAll<HTMLElement>('.mapping-editor')].find(el=>el.dataset.ruleId===focusRule);row?.scrollIntoView({block:'nearest'});row?.querySelector<HTMLInputElement>('input:not([type=checkbox])')?.focus()})}
function openPlan(p?:Plan){editorTrigger=document.activeElement as HTMLElement;hostDraft.value=null;ruleDraft.value=[];planDraft.value=p?clone(p):{id:crypto.randomUUID(),name:'',notes:'',ruleIds:[],autoStart:false};editorKind.value='plan';editorError.value='';editorRevision.value=state.value!.revision;editorBaseConfig.value=cloneConfig();baseline.value=editorState();dialog.value?.showModal()}
function openTemporary(h:Host,r?:Rule,g?:Group){editorTrigger=document.activeElement as HTMLElement;hostDraft.value=null;planDraft.value=null;ruleDraft.value=[r?{...clone(r),id:crypto.randomUUID()}:newRule(h.id)];editorKind.value=g?'adopt':'temporary';adoptGroup.value=g?.id||'';editorError.value='';editorRevision.value=state.value!.revision;editorBaseConfig.value=cloneConfig();baseline.value=editorState();dialog.value?.showModal()}
function finishEditor(){dialog.value?.close();editorKind.value='';hostDraft.value=null;planDraft.value=null;ruleDraft.value=[];editorTrigger?.focus()}
interface Confirmation {title:string;lines:string[];choices:{value:string;label:string;danger?:boolean}[]}
const confirmation=ref<Confirmation|null>(null);let resolveConfirmation:((value:string)=>void)|null=null
function ask(title:string,lines:string[],choices:Confirmation['choices']=[{value:'cancel',label:'取消'},{value:'continue',label:'继续',danger:true}]){confirmation.value={title,lines,choices};confirmDialog.value?.showModal();return new Promise<string>(resolve=>resolveConfirmation=resolve)}
function answerConfirmation(value:string){confirmDialog.value?.close();resolveConfirmation?.(value);resolveConfirmation=null;confirmation.value=null}
async function requestClose(){if(busy('save-editor')||busy('temporary'))return;if(dirty.value){const answer=await ask('保留未保存的修改？',['可以保存后关闭，或返回继续编辑。'],[{value:'cancel',label:'继续编辑'},{value:'discard',label:'放弃修改',danger:true},{value:'save',label:'保存并关闭'}]);if(answer==='cancel')return;if(answer==='save'){await saveDraft();return}}finishEditor()}
function removalLines(ids:string[]){const config=state.value!.config;const names=config.rules.filter(r=>ids.includes(r.id)).map(r=>r.name);const plans=config.plans.filter(p=>p.ruleIds.some(id=>ids.includes(id)));const groups=state.value!.groups.filter(g=>g.desired&&g.rules.some(r=>ids.includes(r.id)));return [`映射：${names.join('、')||'无'}`,`计划引用：${plans.map(p=>p.name).join('、')||'无'}。对应引用将一并移除。`,groups.length?`${groups.length} 个连接仍在运行，删除登记后保留为临时托管映射。`:'没有受影响的运行连接。']}
async function saveDraft(){
 editorError.value=''
 if(planDraft.value&&(!planDraft.value.name.trim()||!planDraft.value.ruleIds.length)){editorError.value='请填写计划名称并至少选择一条映射';return false}
 if(hostDraft.value){const h=hostDraft.value;if(!h.name.trim()||!h.destination.trim()||!h.ssh.trim()||!Number.isInteger(h.timeoutSecs)||h.timeoutSecs<1||h.timeoutSecs>120){editorTab.value='connection';editorError.value='请填写主机名称、SSH 目标、程序，并将超时设置为 1–120 秒';return false}
 const invalid=h.options.find(x=>!x.includes('=')||!x.split('=').slice(1).join('=').trim()||sshOptions.find(d=>d.name.toLowerCase()===optionKey(x))?.restricted);if(invalid){editorTab.value='connection';editorError.value=`参数 ${invalid.split('=')[0]} 无效或须使用专用设置`;return false}
 const numeric=h.options.find(x=>{const name=optionKey(x),d=sshOptions.find(d=>d.name.toLowerCase()===name);if(!d?.numeric)return false;const value=Number(x.split('=').slice(1).join('='));return !Number.isInteger(value)||value<0||name==='port'&&(value<1||value>65535)});if(numeric){editorTab.value='connection';editorError.value=`${numeric.split('=')[0]} 须填写有效整数，SSH 端口范围为 1–65535`;return false}
 const user=h.options.find(x=>optionKey(x)==='user')?.split('=').slice(1).join('=');if(h.destination.includes('@')&&user&&h.destination.replace(/^ssh:\/\//,'').split('@')[0]!==user.replace(/^"|"$/g,'')){editorTab.value='connection';editorError.value='SSH 目标中的用户与 User 覆盖冲突，请只保留一个来源';return false}}
 if(Object.keys(ruleErrors(ruleDraft.value)).length){editorTab.value='mappings';editorError.value='请修正映射行中的端口、地址或冲突后保存';return false}
 const removed=hostDraft.value?(editorBaseConfig.value?.rules.filter(r=>r.hostId===hostDraft.value!.id&&!ruleDraft.value.some(x=>x.id===r.id)).map(r=>r.id)||[]):[]
 if(removed.length&&await ask('保存并删除这些映射？',removalLines(removed))!=='continue')return false
 const ok=await run('save-editor',async()=>{
  const c=clone(editorBaseConfig.value!)
  if(hostDraft.value){const h={...clone(hostDraft.value),configFile:hostDraft.value.configFile?.trim()||null};const i=c.hosts.findIndex(x=>x.id===h.id);if(i<0)c.hosts.push(h);else c.hosts[i]=h;pruneRules(c,removed);c.rules=c.rules.filter(r=>r.hostId!==h.id);c.rules.push(...ruleDraft.value.map(normalizeRule))}
  if(planDraft.value){const p=clone(planDraft.value),i=c.plans.findIndex(x=>x.id===p.id);if(i<0)c.plans.push(p);else c.plans[i]=p}
  if(editorKind.value==='temporary'){lastRequest.value=null;result.value=await api<StartResult>('ensure',{request:{temporary:ruleDraft.value.map(normalizeRule),consumer:'手动临时转发'}});finishEditor();notify(result.value.ready?'临时转发已就绪':'部分临时转发未就绪，请查看运行状态');return}
  if(editorKind.value==='adopt'){await api('adopt',{groupId:adoptGroup.value,rule:normalizeRule(ruleDraft.value[0]!),revision:editorRevision.value})}else await saveConfig(c,editorRevision.value)
  finishEditor();notify('已保存')
 });if(!ok)editorError.value=actionErrors.value['save-editor']||'保存失败，输入已保留';return ok
}
async function removeRule(r:Rule){if(await ask('删除映射登记？',removalLines([r.id]))!=='continue')return;await run(`host:${r.hostId}`,async()=>{const c=cloneConfig();pruneRules(c,[r.id]);await saveConfig(c);notify('映射登记已删除')})}
async function removeHost(h:Host){const ids=hostRules(h.id).map(r=>r.id),running=hostGroups(h.id).filter(g=>g.desired);const choice=await ask(`删除主机“${h.name}”？`,removalLines(ids),[{value:'cancel',label:'取消'},{value:'keep',label:'删除登记，保留运行连接',danger:true},...(running.length?[{value:'stop',label:'停止连接并删除登记',danger:true}]:[])]);if(choice==='cancel')return;await run(`host:${h.id}`,async()=>{if(choice==='stop')await api('stop',{scope:'host',id:h.id});const c=cloneConfig();pruneRules(c,ids);c.hosts=c.hosts.filter(x=>x.id!==h.id);await saveConfig(c);notify('主机登记已删除')})}
async function removePlan(p:Plan){if(await ask(`删除计划“${p.name}”？`,['删除启动清单，正在运行的连接继续保留。'])!=='continue')return;await run(`plan:${p.id}`,async()=>{const c=cloneConfig();c.plans=c.plans.filter(x=>x.id!==p.id);await saveConfig(c);notify('计划已删除')})}
async function ensure(ids:string[],planId?:string,key='start',retry=false){const request={ruleIds:ids,planId,overrides:retry?(lastRequest.value?.overrides||[]):clone(overrides.value)};await run(key,async()=>{const outcome=await api<StartResult>('ensure',{request:{...request,consumer:planId?`计划:${state.value?.config.plans.find(p=>p.id===planId)?.name||planId}`:'手动'}});lastRequest.value=clone(request);result.value=outcome;notify(result.value.ready?'转发已就绪':'部分转发未就绪，请查看对应映射')})}
async function stop(scope:string,id?:string){const groups=state.value!.groups.filter(g=>g.desired&&(scope==='all'||scope==='host'&&g.hostId===id||scope==='group'&&g.id===id));if(!groups.length)return;const labels=[...new Set(groups.flatMap(g=>g.rules.map(r=>r.name)))];if(await ask(scope==='all'?'停止全部托管连接？':scope==='host'?'停止此主机的全部连接？':'停止此连接？',[`影响 ${groups.length} 个连接：${labels.join('、')}`,`使用方：${[...new Set(groups.flatMap(g=>g.consumers))].join('、')||'手动'}`, '停止后取消重连。'])!=='continue')return;await run(`stop:${id||'all'}`,async()=>{await api('stop',{scope,id});notify('已停止')})}
async function restart(g:Group){if(await ask('应用新参数并重启连接？',[`会暂时中断：${g.rules.map(r=>r.name).join('、')}`,'已登记映射使用当前配置，临时映射沿用原有定义；其他连接保持运行。'])!=='continue')return;await run(`restart:${g.id}`,async()=>{await api('stop',{scope:'group',id:g.id});const ids=g.rules.filter(registered).map(r=>r.id),temporary=g.rules.filter(r=>!registered(r)&&!r.id.startsWith('ssh:'));const request={ruleIds:ids,temporary,overrides:[] as string[],consumer:'手动应用参数'};result.value=await api<StartResult>('ensure',{request});lastRequest.value={ruleIds:ids,overrides:[]}})}
async function dismiss(g:Group){await run(`host:${g.hostId}`,()=>api('dismiss',{groupId:g.id}))}
async function copy(text:string){await run('clipboard',async()=>{await navigator.clipboard.writeText(text);notify('已复制')})}
function toggle(id:string){collapsed.value=collapsed.value.includes(id)?collapsed.value.filter(x=>x!==id):[...collapsed.value,id]}
async function showPreview(host:Host,draft=false){await run(draft?'preview-draft':`host:${host.id}`,async()=>{preview.value=await api<Preview>('preview',draft?{host}:{hostId:host.id});previewSearch.value='';previewDialog.value?.showModal()})}
function parameterSource(key:string){if(key==='user'&&preview.value?.host.destination.includes('@'))return 'SSH 目标';if(preview.value?.host.options.some(x=>optionKey(x)===key))return '手动覆盖';if(sshOptions.find(x=>x.name.toLowerCase()===key)?.restricted)return 'Tether 管理';if(['serveraliveinterval','serveralivecountmax'].includes(key))return 'Tether 默认';return '继承配置 / OpenSSH 默认'}
const effectiveRows=computed(()=>Object.entries(preview.value?.effective||{}).filter(([key,value])=>`${key} ${value.join(' ')}`.toLowerCase().includes(previewSearch.value.toLowerCase())))
const planHosts=(p:Plan)=>allHosts.value.filter(h=>hostRules(h.id).some(r=>p.ruleIds.includes(r.id)))
const planRules=(p:Plan,h:Host)=>hostRules(h.id).filter(r=>p.ruleIds.includes(r.id))
async function submitAnswer(){await run('answer',async()=>{await api('answer',{id:currentPrompt.value?.id,answer:answer.value});answer.value=''})}
watch(()=>currentPrompt.value?.id,id=>{if(id!==promptId.value){answer.value='';promptId.value=id??'';void nextTick(()=>document.querySelector<HTMLInputElement>(dialog.value?.open?'#editor-auth-answer':'#auth-answer')?.focus())}})
const settingsDirty=computed(()=>configDraft.value!==configBaseline.value||!!filePanel.value?.isDirty)
async function canLeave(){
 if(dirty.value||settingsDirty.value){if(await ask('放弃未保存的修改？',['切换环境或离开页面后，尚未保存的编辑将被放弃。'],[{value:'cancel',label:'继续编辑'},{value:'continue',label:'放弃修改',danger:true}])!=='continue')return false}
 return true
}
defineExpose({canLeave})
async function navigate(p:string){if(page.value==='设置'&&p!=='设置'&&!await canLeave())return;if(page.value==='设置'&&p!=='设置'){configDraft.value=configBaseline.value}page.value=p}
function chooseEnvironment(){emit('enumerate');environmentDialog.value?.showModal()}
function switchTo(distro?:string){environmentDialog.value?.close();emit('switch',distro)}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||settingsDirty.value){event.preventDefault();event.returnValue=''}}
function shortcut(event:KeyboardEvent){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'&&dialog.value?.open&&!confirmDialog.value?.open){event.preventDefault();void saveDraft()}}
onMounted(async()=>{applyTheme();await refresh();timer=setInterval(()=>void refresh(),1000);window.addEventListener('beforeunload',beforeUnload);window.addEventListener('keydown',shortcut)})
onUnmounted(()=>{clearInterval(timer);clearTimeout(noticeTimer);media.removeEventListener('change',applyTheme);window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('keydown',shortcut)})
</script>
<template>
<div ref="shell" class="shell">
 <aside>
  <div class="brand"><span class="mark"><UiIcon name="link" :size="20" /></span><div class="brand-copy"><strong>Tether</strong><span>SSH 转发</span></div></div>
  <nav aria-label="主要导航"><button v-for="item in navigation" :key="item.label" :class="{active:page===item.label}" :aria-current="page===item.label?'page':undefined" :aria-label="item.label" :title="item.label" @click="navigate(item.label)"><UiIcon :name="item.icon" :size="19" /><span class="nav-label">{{item.label}}</span></button></nav>
  <div class="sidebar-footer">
   <div class="environment"><span class="sidebar-label">运行环境</span><button :disabled="switching" :title="environment.label" @click="chooseEnvironment"><UiIcon name="monitor" :size="14" /><span>{{switching?'连接中…':environment.label}}</span></button></div>
   <label class="theme"><span class="sidebar-label">外观</span><select v-model="theme" aria-label="外观主题" @change="run('theme',async()=>{const c=cloneConfig();c.theme=theme as Config['theme'];await saveConfig(c)})"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></label>
  </div>
 </aside>
 <main>
 <p v-if="environmentError" class="message error" role="alert"><UiIcon name="alert" :size="16" />{{environmentError}}</p>
 <header><div class="page-heading"><h1>{{page}}</h1><p class="page-meta">{{pageMeta}}</p></div><div class="actions page-actions"><button class="icon-button" ref="helpTrigger" title="使用说明" aria-label="使用说明" @click="help?.showModal()"><UiIcon name="help" /><span class="sr-only">使用说明</span></button><button class="icon-button" title="刷新" aria-label="刷新" @click="refresh"><UiIcon name="refresh" /><span class="sr-only">刷新</span></button></div></header>
 <div v-if="error||state?.configError" class="message error" role="alert"><UiIcon name="alert" :size="16" /><span>{{error||state?.configError}}</span><button @click="run('reload',async()=>{await api('reload');error=''})">重新加载配置</button><button v-if="error&&!state?.configError" class="icon-button" title="关闭" aria-label="关闭" @click="error=''"><UiIcon name="close" :size="15" /><span class="sr-only">关闭</span></button></div>
 <div v-if="notice" class="message notice" role="status"><UiIcon name="check" :size="15" /><span>{{notice}}</span></div>
 <div v-for="key in ['theme','reload','clipboard','settings','keys','start','sort']" :key="key"><div v-if="actionErrors[key]" class="message error" role="alert"><UiIcon name="alert" :size="16" /><span>{{actionErrors[key]}}</span><button class="icon-button" title="关闭" aria-label="关闭" @click="delete actionErrors[key]"><UiIcon name="close" :size="15" /><span class="sr-only">关闭</span></button></div></div>
 <AuthenticationPrompt v-if="currentPrompt" v-model="answer" :prompt="currentPrompt" :count="state?.prompts.length||0" input-id="auth-answer" :busy="busy('answer')" :error="actionErrors.answer" @submit="submitAnswer" @cancel="run('answer',()=>api('cancelPrompt',{id:currentPrompt!.id}))" />
 <template v-if="page==='主机'">
 <div class="toolbar"><input v-model="search" class="search-input" aria-label="搜索主机或映射" placeholder="搜索主机、映射或端口"><select v-model="filter" aria-label="筛选映射状态"><option value="all">全部状态</option><option value="running">运行中</option><option value="idle">未启动</option><option value="error">异常 / 待处理</option></select><span class="toolbar-spacer"></span><button class="primary" :disabled="!state" @click="openHost()"><UiIcon name="plus" :size="17" /><span>添加主机</span></button><button v-if="selected.length" class="icon-button" :title="`启动所选 ${selected.length} 条映射`" :aria-label="`启动所选 ${selected.length} 条映射`" :disabled="busy('start')" @click="ensure(selected)"><UiIcon name="play" :size="16" /><span class="sr-only">启动所选</span></button><button v-if="selected.length" class="icon-button" title="清空选择" aria-label="清空选择" @click="selected=[]"><UiIcon name="close" /><span class="sr-only">清空选择</span></button><button class="icon-button danger stop-all" title="停止全部托管连接" aria-label="停止全部托管连接" :disabled="!activeCount||busy('stop:all')" @click="stop('all')"><UiIcon name="power" /><span class="sr-only">停止全部托管</span></button></div>
 <p v-if="state?.externalCheckError" class="message muted" role="status"><UiIcon name="terminal" :size="15" />终端连接检测暂不可用：{{state.externalCheckError}}</p>
 <details class="temporary-options"><summary><UiIcon name="sliders" :size="16" /><span>本次启动参数覆盖</span><UiIcon name="chevron-down" :size="15" class="summary-chevron" /></summary><OptionsEditor v-model="overrides" /></details>
 <div v-if="state&&!allHosts.length" class="empty"><span class="empty-icon"><UiIcon name="host" :size="26" /></span><h2>添加第一台 SSH 主机</h2><p>填写 SSH 别名或目标，并在主机内添加端口映射。</p><button class="primary" @click="openHost()"><UiIcon name="plus" :size="17" /><span>添加主机</span></button></div><p v-else-if="state&&!hosts.length" class="empty compact">没有匹配的主机或映射。<button class="text-button" @click="search='';filter='all'">清除筛选</button></p><p v-if="!state&&!error" class="empty" role="status">正在读取主机…</p>
 <section v-for="h in hosts" :key="h.id" class="host" :data-sort-id="isHostRegistered(h.id)?h.id:undefined" data-sort-group="hosts">
  <div class="host-heading"><div class="host-title"><SortHandle v-if="isHostRegistered(h.id)" :label="h.name" :disabled="busy('sort')" /><button class="disclosure" :title="`${collapsed.includes(h.id)?'展开':'收起'} ${h.name}`" :aria-expanded="!collapsed.includes(h.id)" :aria-label="`${collapsed.includes(h.id)?'展开':'收起'} ${h.name}`" @click="toggle(h.id)"><UiIcon name="chevron-down" :size="16" /></button><div class="host-copy"><h2>{{h.name}} <span :class="['latency',busy(`test:${h.id}`)?'testing':state?.latency[h.id]!=null?'measured':Object.prototype.hasOwnProperty.call(state?.latency||{},h.id)?'unavailable':'']" role="status" title="SSH 目标的 TCP 响应时间，不代表认证成功；跳板目标无数据">{{busy(`test:${h.id}`)?'测试中…':state?.latency[h.id]!=null?`${state.latency[h.id]} ms`:Object.prototype.hasOwnProperty.call(state?.latency||{},h.id)?'无法测量':'—'}}</span></h2><p><span class="host-destination">{{h.destination}}</span><span v-if="h.notes" class="host-note">{{h.notes}}</span><span class="host-count">{{displayRules(h.id).length}} 条映射</span><span v-if="!isHostRegistered(h.id)" class="badge">临时托管主机</span></p></div></div><div class="actions host-actions"><button v-if="isHostRegistered(h.id)" class="icon-button" title="编辑主机" aria-label="编辑主机" :disabled="busy(`host:${h.id}`)" @click="openHost(h)"><UiIcon name="edit" /><span class="sr-only">编辑主机</span></button><button v-if="isHostRegistered(h.id)" class="primary add-mapping" title="添加映射" aria-label="添加映射" @click="openHost(h,'mappings',true)"><UiIcon name="plus" :size="17" /><span>添加映射</span></button><button class="icon-button" title="启动全部映射" aria-label="启动全部映射" :disabled="!hostRules(h.id).length||busy(`host:${h.id}`)" @click="ensure(hostRules(h.id).map(r=>r.id),undefined,`host:${h.id}`)"><UiIcon name="play" /><span class="sr-only">启动全部映射</span></button><button class="icon-button danger" title="停止此主机" aria-label="停止此主机" :disabled="!hostGroups(h.id).some(g=>g.desired)||busy(`stop:${h.id}`)" @click="stop('host',h.id)"><UiIcon name="stop" /><span class="sr-only">停止此主机</span></button><details class="row-menu host-menu"><summary title="更多主机操作" aria-label="更多主机操作"><UiIcon name="more" /><span class="sr-only">主机操作</span></summary><div class="menu-panel"><button v-if="isHostRegistered(h.id)" :disabled="busy(`test:${h.id}`)" @click="run(`test:${h.id}`,async()=>{const r=await api<{milliseconds:number|null}>('test',{hostId:h.id});if(state)state.latency[h.id]=r.milliseconds})"><UiIcon name="activity" :size="16" /><span>{{busy(`test:${h.id}`)?'测试中…':'测试 TCP 响应'}}</span></button><button v-if="isHostRegistered(h.id)" @click="showPreview(h)"><UiIcon name="sliders" :size="16" /><span>生效参数</span></button><button v-if="isHostRegistered(h.id)" @click="openTemporary(h)"><UiIcon name="zap" :size="16" /><span>临时转发</span></button><button v-if="isHostRegistered(h.id)" class="danger" @click="removeHost(h)"><UiIcon name="trash" :size="16" /><span>删除主机</span></button></div></details></div></div>
  <p v-if="actionErrors[`test:${h.id}`]" class="message error" role="alert"><UiIcon name="alert" :size="15" />{{actionErrors[`test:${h.id}`]}}</p>
  <div v-if="actionErrors[`host:${h.id}`]" class="message error" role="alert"><UiIcon name="alert" :size="15" /><span>{{actionErrors[`host:${h.id}`]}}</span><button class="icon-button" title="关闭" aria-label="关闭" @click="delete actionErrors[`host:${h.id}`]"><UiIcon name="close" :size="15" /><span class="sr-only">关闭</span></button></div>
  <div v-show="!collapsed.includes(h.id)">
   <p v-if="!displayRules(h.id).length" class="empty compact">还没有端口映射。<button class="text-button" @click="openHost(h,'mappings',true)">添加第一条映射</button></p>
   <div v-for="r in visibleRules(h.id)" :key="r.id" class="rule registered" :data-sort-id="registered(r)?r.id:undefined" :data-sort-group="`rules:${h.id}`">
    <div class="rule-summary"><label class="rule-name"><input v-if="registered(r)" v-model="selected" type="checkbox" :value="r.id" :aria-label="`选择 ${r.name}`"><span class="rule-copy"><strong>{{r.name}}</strong><small v-if="!registered(r)">{{r.id.startsWith('ssh:')?'SSH 配置来源':'临时映射'}}</small></span></label><code class="rule-endpoint">{{endpoint(r)}}</code><span :class="['status',ruleState(r)]">{{ruleState(r)==='idle'?'未启动':ruleState(r)==='running'?'已启动':states[ruleState(r)]||ruleState(r)}}<small v-if="externalMatch(r)&&!ruleGroup(r)?.desired" :title="externalMatch(r)!.reason">{{externalMatch(r)!.source?' · '+externalMatch(r)!.source:''}}</small></span></div>
    <div class="actions rule-actions"><SortHandle v-if="registered(r)" :label="r.name" :disabled="busy('sort')" /><button v-if="registered(r)" class="icon-button" title="启动 / 复用" aria-label="启动 / 复用" :disabled="busy(`host:${h.id}`)||(!!ruleGroup(r)?.desired&&!pending(r))||!!externalMatch(r)&&!['idle','unverified'].includes(externalMatch(r)!.state)" @click="ensure([r.id],undefined,`host:${h.id}`)"><UiIcon name="play" /><span class="sr-only">{{busy(`host:${h.id}`)?'处理中…':'启动 / 复用'}}</span></button><button class="icon-button" title="复制地址" aria-label="复制地址" @click="copy(browserAddress(r))"><UiIcon name="copy" /><span class="sr-only">复制地址</span></button><details class="row-menu"><summary title="映射更多操作" aria-label="映射更多操作"><UiIcon name="more" /><span class="sr-only">更多</span></summary><div class="menu-panel"><button v-if="registered(r)" @click="openHost(h,'mappings',false,r.id)"><UiIcon name="edit" :size="16" /><span>编辑映射</span></button><button v-if="!registered(r)&&!r.id.startsWith('ssh:')&&isHostRegistered(h.id)&&ruleGroup(r)?.desired" @click="openTemporary(h,r,ruleGroup(r))"><UiIcon name="zap" :size="16" /><span>保存为映射</span></button><button @click="copy(r.id)"><UiIcon name="copy" :size="16" /><span>复制规则 ID</span></button><button v-if="registered(r)" class="danger" @click="removeRule(r)"><UiIcon name="trash" :size="16" /><span>删除登记</span></button></div></details></div>
    <p v-if="externalMatch(r)" class="muted detection-detail">{{externalMatch(r)!.reason}}<span v-if="externalMatch(r)!.process"> · {{externalMatch(r)!.process}}</span> · {{new Date(externalMatch(r)!.checkedAt).toLocaleTimeString()}}</p><p v-if="r.notes" class="muted rule-note">{{r.notes}}</p><p v-if="ruleGroup(r)?.error&&!externalMatch(r)" class="error rule-error" role="alert">{{ruleGroup(r)!.error}}</p>
   </div>
   <details v-if="hostGroups(h.id).length" class="connection-details"><summary><UiIcon name="terminal" :size="15" /><span>当前连接 · {{hostGroups(h.id).length}}</span><UiIcon name="chevron-down" :size="14" class="summary-chevron" /></summary><section v-for="(g,i) in hostGroups(h.id)" :key="g.id" class="group"><div class="group-heading"><strong>连接 {{i+1}} · {{g.rules.length}} 条映射</strong><span :class="['status',g.state]">{{states[g.state]}}</span><button v-if="g.desired" class="danger" :disabled="busy(`stop:${g.id}`)" @click="stop('group',g.id)">停止连接 · {{g.rules.length}} 条映射</button><button v-if="g.desired&&groupPending(g)" :disabled="busy(`restart:${g.id}`)" @click="restart(g)">应用参数并重启</button><button v-if="g.state==='failed'" @click="dismiss(g)">关闭失败提示</button></div><p>{{g.rules.map(r=>r.name).join('、')}}</p><p class="muted">使用方：{{g.consumers.join('、')||'手动'}} · PID {{g.pid??'—'}}</p><p v-if="g.error" class="error">{{g.error}}</p><p v-if="actionErrors[`stop:${g.id}`]||actionErrors[`restart:${g.id}`]" class="error" role="alert">{{actionErrors[`stop:${g.id}`]||actionErrors[`restart:${g.id}`]}}</p><details><summary><UiIcon name="terminal" :size="14" /><span>执行参数与日志</span><UiIcon name="chevron-down" :size="13" class="summary-chevron" /></summary><pre>{{g.args.join('\n')}}</pre><pre class="logs">{{g.logs.join('\n')||'暂无日志'}}</pre><button class="text-button" @click="copy(g.id)">复制连接 ID</button></details></section></details>
  </div>
 </section>

 </template>
 <template v-if="page==='计划'"><div class="toolbar"><span class="toolbar-label">启动清单只引用映射，不拥有连接</span><span class="toolbar-spacer"></span><button class="primary" :disabled="!state" @click="openPlan()"><UiIcon name="plus" :size="17" /><span>新建计划</span></button></div><div v-if="state&&!state.config.plans.length" class="empty"><span class="empty-icon"><UiIcon name="plan" :size="26" /></span><h2>还没有计划</h2><p>选择不同主机下的映射，保存为启动清单。</p></div><section v-for="p in state?.config.plans" :key="p.id" class="host plan-card" :data-sort-id="p.id" data-sort-group="plans"><div class="host-heading"><div class="host-title"><SortHandle :label="p.name" :disabled="busy('sort')" /><span class="plan-mark"><UiIcon name="plan" :size="19" /></span><div class="host-copy"><h2>{{p.name}} <span v-if="p.autoStart" class="badge">首次激活时执行</span></h2><p>{{planHosts(p).length}} 台主机 · {{p.ruleIds.length}} 条映射<span v-if="p.notes" class="host-note">{{p.notes}}</span></p></div></div><div class="actions host-actions"><button class="primary" :disabled="!p.ruleIds.length||busy(`plan:${p.id}`)" @click="ensure([],p.id,`plan:${p.id}`)"><UiIcon name="play" :size="16" /><span>{{busy(`plan:${p.id}`)?'启动中…':'启动计划'}}</span></button><button class="icon-button" title="编辑计划" aria-label="编辑计划" @click="openPlan(p)"><UiIcon name="edit" /><span class="sr-only">编辑</span></button><button class="icon-button danger" title="删除计划" aria-label="删除计划" @click="removePlan(p)"><UiIcon name="trash" /><span class="sr-only">删除计划</span></button></div></div><p v-if="actionErrors[`plan:${p.id}`]" class="message error" role="alert"><UiIcon name="alert" :size="15" />{{actionErrors[`plan:${p.id}`]}}</p><p v-if="!p.ruleIds.length" class="message"><UiIcon name="alert" :size="15" />计划中已无映射，请编辑后选择。</p><details class="plan-details"><summary>查看所选映射<span class="summary-count">{{p.ruleIds.length}}</span><UiIcon name="chevron-down" :size="15" class="summary-chevron" /></summary><div v-for="h in planHosts(p)" :key="h.id" class="plan-host-group"><strong>{{h.name}}</strong><ul><li v-for="r in planRules(p,h)" :key="r.id"><span>{{r.name}}</span><code>{{endpoint(r)}}</code></li></ul></div><button class="text-button" @click="copy(p.id)"><UiIcon name="copy" :size="14" />复制计划 ID</button></details></section></template>
 <KeysPanel v-if="page==='密钥'&&state" :config="state.config" :revision="state.revision" @refresh="refresh" @notice="notify" />
 <template v-if="page==='设置'">
 <FilePanel v-if="state" ref="filePanel" :config="state.config" :ask="ask" @refresh="refresh" @notice="notify" />
 <details class="panel raw-config"><summary @click="()=>{if(!configDraft){configDraft=JSON.stringify(state?.config,null,2);configBaseline=configDraft;configRevision=state!.revision}}"><UiIcon name="sliders" :size="16" /><span>高级 · 原始配置 JSON</span><UiIcon name="chevron-down" :size="15" class="summary-chevron" /></summary><p class="muted break">{{state?.configPath}}</p><label>规则、计划、文件引用和设备设置<textarea v-model="configDraft" rows="18" spellcheck="false"></textarea></label><button class="primary" :disabled="busy('settings')" @click="run('settings',async()=>{await saveConfig(JSON.parse(configDraft),configRevision);configRevision=(await api<State>('status')).revision;configBaseline=configDraft;notify('配置已保存')})">保存配置</button></details>
 </template>
 <section v-if="result&&(page==='主机'||page==='计划')" class="panel start-results" aria-label="启动结果"><div class="panel-heading"><div><span class="eyebrow">本次执行</span><h2>启动结果</h2></div><button class="icon-button" title="关闭结果" aria-label="关闭结果" @click="result=null"><UiIcon name="close" /><span class="sr-only">关闭结果</span></button></div><div class="result-counts" role="status"><span><strong>{{resultCounts.reused}}</strong> 复用</span><span><strong>{{resultCounts.started}}</strong> 新启动</span><span :class="{danger:resultCounts.failed}"><strong>{{resultCounts.failed}}</strong> 未就绪</span></div><button v-if="failedIds.length" :disabled="busy('start')" @click="ensure(failedIds,undefined,'start',true)"><UiIcon name="refresh" :size="16" /><span>仅重试未就绪项</span></button><details><summary>逐项结果</summary><ul><li v-for="r in result.results" :key="r.ruleId"><span>{{state?.config.rules.find(x=>x.id===r.ruleId)?.name||state?.groups.flatMap(g=>g.rules).find(x=>x.id===r.ruleId)?.name||'临时 / 来源映射'}}</span><span :class="['status',r.state]">{{states[r.state]||r.state}}{{r.reused?' · 已复用':''}}</span><span v-if="r.error" class="error">{{r.error}}</span></li></ul></details></section>
 </main>
 <dialog v-dialog-dismiss="()=>environmentDialog?.close()" ref="environmentDialog" class="environment-dialog" aria-labelledby="environment-title"><div class="dialog-heading"><div><span class="eyebrow">本机与 WSL</span><h2 id="environment-title">选择运行环境</h2></div><button class="icon-button" title="关闭" aria-label="关闭" @click="environmentDialog?.close()"><UiIcon name="close" /><span class="sr-only">关闭</span></button></div><div class="environment-options"><button @click="switchTo()"><UiIcon name="monitor" :size="17" /><span>{{environment.id==='linux'?'Linux':'Windows'}}</span></button><button v-for="d in distributions" :key="d.name" @click="switchTo(d.name)"><UiIcon name="terminal" :size="17" /><span>WSL · {{d.name}}</span><small>{{d.running?'运行中':'尚未启动'}}</small></button></div><p v-if="!distributions.length" class="muted">没有可用的 WSL 2 用户发行版，当前环境保持不变。</p></dialog>
 <dialog v-dialog-dismiss="()=>help?.close()" ref="help" class="help-dialog" aria-labelledby="help-title" @close="helpTrigger?.focus()"><header class="dialog-heading"><div><span class="eyebrow">Tether</span><h2 id="help-title">使用说明</h2></div><button class="icon-button" title="关闭说明" aria-label="关闭说明" @click="help?.close()"><UiIcon name="close" /><span class="sr-only">关闭说明</span></button></header><DocumentContent :text="userGuide" hide-title /></dialog>
 <dialog v-dialog-dismiss="requestClose" ref="dialog" class="editor-dialog" aria-labelledby="editor-title" @cancel.prevent="requestClose"><div class="dialog-heading"><div><span class="eyebrow">{{editorKind==='temporary'?'临时托管':editorKind==='adopt'?'运行映射':'配置'}}</span><h2 id="editor-title">{{editorKind==='host'?'编辑主机':editorKind==='plan'?'启动计划':editorKind==='adopt'?'保存运行映射':'临时转发'}}</h2></div><button class="icon-button" type="button" title="关闭编辑" aria-label="关闭编辑" @click="requestClose"><UiIcon name="close" /><span class="sr-only">关闭编辑</span></button></div><AuthenticationPrompt v-if="currentPrompt" v-model="answer" :prompt="currentPrompt" :count="state?.prompts.length||0" input-id="editor-auth-answer" :busy="busy('answer')" :error="actionErrors.answer" @submit="submitAnswer" @cancel="run('answer',()=>api('cancelPrompt',{id:currentPrompt!.id}))" /><form novalidate @submit.prevent="saveDraft">
 <HostEditor v-if="hostDraft" v-model="hostDraft" v-model:rules="ruleDraft" :tab="editorTab" @tab="editorTab=$event" @preview="showPreview(hostDraft!,true)" @copy-id="copy" />
 <PlanEditor v-else-if="planDraft" v-model="planDraft" :hosts="state?.config.hosts||[]" :rules="state?.config.rules||[]" />
 <template v-else-if="ruleDraft.length"><label>主机<select v-model="ruleDraft[0]!.hostId" @change="ruleDraft.forEach(r=>r.hostId=ruleDraft[0]!.hostId)" :disabled="editorKind==='adopt'"><option v-for="h in state?.config.hosts" :key="h.id" :value="h.id">{{h.name}}</option></select></label><RulesEditor v-model="ruleDraft" :host-id="ruleDraft[0]!.hostId" :locked="editorKind==='adopt'" @copy-id="copy" /></template>
 <p v-if="editorError||actionErrors['preview-draft']" class="message error" role="alert"><UiIcon name="alert" :size="15" />{{editorError||actionErrors['preview-draft']}}</p><footer><span v-if="dirty" class="dirty-mark"><span></span>有未保存的修改</span><button type="button" :disabled="busy('save-editor')" @click="requestClose">取消</button><button class="primary" :disabled="busy('save-editor')">{{busy('save-editor')?'处理中…':editorKind==='temporary'?'启动临时转发':'保存'}}</button></footer></form></dialog>
 <dialog v-dialog-dismiss="()=>previewDialog?.close()" ref="previewDialog" class="preview-dialog" aria-labelledby="preview-title"><div class="dialog-heading"><div><span class="eyebrow">OpenSSH</span><h2 id="preview-title">{{preview?.host.name}} · 生效参数</h2></div><button class="icon-button" title="关闭" aria-label="关闭" @click="previewDialog?.close()"><UiIcon name="close" /><span class="sr-only">关闭</span></button></div><label class="search-label">搜索生效参数<input v-model="previewSearch" placeholder="名称或值"></label><p class="muted">继承配置与 OpenSSH 默认值由本机客户端解析，不回写原始文件。</p><dl class="effective-list"><template v-for="[key,values] in effectiveRows" :key="key"><dt>{{sshOptions.find(x=>x.name.toLowerCase()===key)?.label||key}}<small>{{key}} · {{parameterSource(key)}}</small></dt><dd><code>{{values.join('\n')}}</code></dd></template></dl><details v-if="preview?.inheritedForwards.length"><summary><UiIcon name="link" :size="15" /><span>SSH 配置中的转发</span><UiIcon name="chevron-down" :size="14" class="summary-chevron" /></summary><ul><li v-for="line in preview.inheritedForwards" :key="line"><code>{{line}}</code></li></ul></details></dialog>
 <dialog v-dialog-dismiss="()=>answerConfirmation('cancel')" ref="confirmDialog" class="confirm-dialog" aria-labelledby="confirm-title" @cancel.prevent="answerConfirmation('cancel')"><div class="dialog-heading"><div class="confirm-title"><div class="confirm-mark"><UiIcon name="alert" :size="22" /></div><h2 id="confirm-title">{{confirmation?.title}}</h2></div><button type="button" class="icon-button" title="关闭确认" aria-label="关闭确认" @click="answerConfirmation('cancel')"><UiIcon name="close" /><span class="sr-only">关闭确认</span></button></div><ul><li v-for="line in confirmation?.lines" :key="line">{{line}}</li></ul><footer><button v-for="choice in confirmation?.choices" :key="choice.value" :class="{danger:choice.danger,primary:choice.value==='save'}" @click="answerConfirmation(choice.value)">{{choice.label}}</button></footer></dialog>
</div>
</template>
